-- Add all Japanese and Simplified Chinese 30th Celebration printings with verified scans.
-- Existing printings are preserved; this only fills image_url when it is currently NULL.

-- Normalize these two existing set rows to the language codes used by the collection UI.
UPDATE public.foreign_card_sets
SET language_code = 'JP'
WHERE set_code = 'M6a' AND market_code = 'JP' AND language_code = 'ja';

UPDATE public.foreign_card_sets
SET language_code = 'ZH-CN'
WHERE set_code = '30thC' AND market_code = 'CN' AND language_code = 'zh-CN';

