    language_code text,
    set_code text,
    market_code text,
    catalog_card_id uuid,
    collector_number text,
    card_name text,
    image_url text
  )
)
INSERT INTO public.foreign_card_printings (
  foreign_set_id, catalog_card_id, collector_number, card_name,
  variant_keys, image_url, source_name, source_url, validation_status
)
SELECT
  fs.id,
  seed.catalog_card_id,
  seed.collector_number,
  seed.card_name,
  ARRAY['holo']::text[],
  seed.image_url,
  'TCG Collector',
  CASE seed.language_code
    WHEN 'JP' THEN 'https://www.tcgcollector.com/sets/11823/30th-celebration?setCardCountMode=anyCardVariant'
    ELSE 'https://www.tcgcollector.com/sets/11824/30th-celebration'
  END,
  'verified'
FROM seed
JOIN public.foreign_card_sets fs
  ON fs.language_code = seed.language_code
 AND fs.market_code = seed.market_code
 AND fs.set_code = seed.set_code
ON CONFLICT (foreign_set_id, catalog_card_id, collector_number)
DO UPDATE SET image_url = EXCLUDED.image_url
WHERE public.foreign_card_printings.image_url IS NULL;

DO $$
DECLARE
  japanese_count integer;
  chinese_count integer;
  japanese_missing_images integer;
  chinese_missing_images integer;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE p.image_url IS NULL)
  INTO japanese_count, japanese_missing_images
  FROM public.foreign_card_printings p
  JOIN public.foreign_card_sets s ON s.id = p.foreign_set_id
  WHERE s.language_code = 'JP' AND s.market_code = 'JP' AND s.set_code = 'M6a';

  SELECT count(*), count(*) FILTER (WHERE p.image_url IS NULL)
  INTO chinese_count, chinese_missing_images
  FROM public.foreign_card_printings p
  JOIN public.foreign_card_sets s ON s.id = p.foreign_set_id
  WHERE s.language_code = 'ZH-CN' AND s.market_code = 'CN' AND s.set_code = '30thC';

  IF japanese_count <> 176 OR chinese_count <> 176
     OR japanese_missing_images <> 0 OR chinese_missing_images <> 0 THEN
    RAISE EXCEPTION '30th Celebration seed verification failed: JP %, CN %, missing images JP %, CN %',
      japanese_count, chinese_count, japanese_missing_images, chinese_missing_images;
  END IF;
END $$;
